-- ==========================================================================================
-- 11_verify.sql  ·  Reconciliation: Snowflake figures vs. the figures the portal shows
-- Each row: what the portal says, what Snowflake computes, and whether they agree.
-- ==========================================================================================
USE ROLE LUZ_ADMIN;
USE WAREHOUSE LUZ_APP_WH;
USE DATABASE LUZSAUDE_DEMO;

CREATE OR REPLACE VIEW OPS.PORTAL_RECONCILIATION AS
WITH c AS (
  SELECT 'Hospitais' k, 15 portal, (SELECT COUNT(*) FROM REF.HOSPITALS)::FLOAT snow, 0 tol UNION ALL
  SELECT 'Camas', 1880, (SELECT SUM(BEDS) FROM REF.HOSPITALS), 0 UNION ALL
  SELECT 'Clínicas', 24, (SELECT COUNT(*) FROM REF.CLINICS), 0 UNION ALL
  SELECT 'Colaboradores', 14012, (SELECT COUNT(*) FROM CORE.DIM_EMPLOYEE), 0 UNION ALL
  SELECT 'Perfis Doente 360°', 240, (SELECT COUNT(*) FROM REF.PATIENT_PROFILES), 0 UNION ALL
  SELECT 'Perfis Colaborador 360°', 183, (SELECT COUNT(*) FROM REF.EMPLOYEE_PROFILES), 0 UNION ALL
  SELECT 'Receita jan-out 2026 (M€)', 756.2, (SELECT ROUND(SUM(AMOUNT_EUR) / 1e6, 1) FROM CORE.INVOICE WHERE SERVICE_DATE BETWEEN '2026-01-01' AND '2026-10-31'), 0.5 UNION ALL
  SELECT 'Previsão de fecho 2026 (M€)', 875, (SELECT ROUND(FORECAST_CLOSE_2026_MEUR, 1) FROM ML.REVENUE_CLOSE_2026), 5 UNION ALL
  SELECT 'Episódios de urgência por dia', 2290, (SELECT ROUND(SUM(ER_VISITS) / COUNT(DISTINCT KPI_DATE)) FROM CORE.HOSPITAL_DAY_KPI WHERE KPI_DATE >= '2026-10-13'), 100 UNION ALL
  SELECT 'Espera média na urgência (min)', 38, (SELECT ROUND(AVG(WAIT_FIRST_PHYSICIAN_MIN), 1) FROM CORE.ER_EPISODE), 2 UNION ALL
  SELECT 'Ocupação do grupo, 30 dias (%)', 85.6, (SELECT ROUND(100 * SUM(BEDS_OCCUPIED) / SUM(BEDS), 1) FROM CORE.HOSPITAL_DAY_KPI WHERE KPI_DATE >= '2026-10-13'), 1.5 UNION ALL
  SELECT 'Ocupação HL Lisboa, esta semana (%)', 91.2, (SELECT ROUND(100 * SUM(BEDS_OCCUPIED) / SUM(BEDS), 1) FROM CORE.HOSPITAL_DAY_KPI WHERE HOSPITAL = 'HL Lisboa' AND KPI_DATE BETWEEN '2026-11-05' AND '2026-11-11'), 1.5 UNION ALL
  SELECT 'Readmissões a 30 dias (%)', 6.5, (SELECT ROUND(100 * AVG(IFF(READMITTED_30D, 1, 0)), 2) FROM CORE.INPATIENT_EPISODE WHERE DISCHARGE_DATE < '2026-10-12'), 0.5 UNION ALL
  SELECT 'Cirurgias por ano', 41200, (SELECT COUNT(*) FROM CORE.SURGERY), 800 UNION ALL
  SELECT 'Limpeza Sala 4 HL Lisboa (min)', 34, (SELECT ROUND(AVG(TURNOVER_MIN)) FROM CORE.SURGERY WHERE ROOM_ID = 'H01-OR04'), 1 UNION ALL
  SELECT 'Taxa de faltas, 30 dias (%)', 8.4, (SELECT ROUND(100 * COUNT_IF(NO_SHOW) / COUNT_IF(STATUS <> 'Marcada'), 2) FROM CORE.APPOINTMENT WHERE APPOINTMENT_DATE >= '2026-10-12'), 0.6 UNION ALL
  SELECT 'Marcações pela app MY LUZ (%)', 41, (SELECT ROUND(100 * AVG(IFF(BOOKING_CHANNEL = 'App MY LUZ', 1, 0)), 1) FROM CORE.APPOINTMENT), 1 UNION ALL
  SELECT 'Taxa de rejeição (%)', 3.4, (SELECT ROUND(100 * COUNT_IF(IS_REJECTED) / COUNT_IF(STATUS <> 'Por enviar'), 2) FROM CORE.INVOICE), 0.3 UNION ALL
  SELECT 'Rejeição AdvanceCare em outubro (%)', 3.1, (SELECT ROUND(100 * COUNT_IF(IS_REJECTED) / COUNT_IF(STATUS <> 'Por enviar'), 2) FROM CORE.INVOICE WHERE PAYER = 'AdvanceCare' AND SERVICE_DATE BETWEEN '2026-10-01' AND '2026-10-31'), 0.4 UNION ALL
  SELECT 'Rejeição AdvanceCare desde 1/11 (%)', 4.9, (SELECT ROUND(100 * COUNT_IF(IS_REJECTED) / COUNT_IF(STATUS <> 'Por enviar'), 2) FROM CORE.INVOICE WHERE PAYER = 'AdvanceCare' AND SERVICE_DATE >= '2026-11-01'), 0.5 UNION ALL
  SELECT 'Notas clínicas analisadas pela IA', 3412, (SELECT COUNT(*) FROM AI.CLINICAL_NOTE_SIGNALS), 0 UNION ALL
  SELECT 'NPS do grupo', 71, (SELECT ROUND(100 * (COUNT_IF(NPS_SCORE >= 9) - COUNT_IF(NPS_SCORE <= 6)) / COUNT(*)) FROM RAW.CUSTOMER_FEEDBACK WHERE CHANNEL = 'Inquérito NPS'), 2 UNION ALL
  SELECT 'Mínima Lisboa sexta 13/11 (°C)', 6, (SELECT TEMP_MIN_C FROM EXT.WEATHER_DAILY WHERE DISTRICT = 'Lisboa' AND OBS_DATE = '2026-11-13'), 0
)
SELECT k AS INDICADOR, portal AS PORTAL, snow AS SNOWFLAKE, IFF(ABS(snow - portal) <= tol, 'OK', 'DESVIO') AS ESTADO FROM c;

SELECT * FROM OPS.PORTAL_RECONCILIATION;
SELECT COUNT_IF(ESTADO = 'OK') AS OK, COUNT_IF(ESTADO <> 'OK') AS DESVIOS FROM OPS.PORTAL_RECONCILIATION;
